/* part:page.script.preview.kit.qr-code */
/* The catalog's live preview of kit.qr-code. It rides with the kit and only the catalog page loads it: `adp.py take` leaves it out. */
(function () {
'use strict';
const { html, useState, useEffect, useRef } = window.htmPreact;
const P = window.CatalogPreviews = window.CatalogPreviews || {};
const K = () => window.Kit;
const first = (samples, part) => samples[Object.keys(samples).find(k => k.endsWith('/' + part + '.json'))];
const Sim = ({ children }) => html`<p class="pv-sim"><b>Sandbox</b> ${children}</p>`;
const Cases = ({ d, value, set, label = 'Use case' }) => html`<div class="pv-row" role="group" aria-label=${label}><span class="pv-label">${label}</span>
  ${d.cases.map(c => html`<button type="button" key=${c.id} class=${'pv-btn' + (c.id === value ? ' pri' : '')} aria-pressed=${c.id === value} onClick=${() => set(c.id)}>${c.label}</button>`)}</div>`;
const LOG = 'margin:0;font:13px/1.45 var(--f-ui);color:var(--ink-2);min-width:0;flex:1 1 14rem';

P['kit.qr-code'] = ({ samples }) => {
  const d = first(samples, 'qr-code');
  const [id, setId] = useState(d.cases[0].id);
  const c = d.cases.find(x => x.id === id);
  const [text, setText] = useState(c.text);
  const [ecc, setEcc] = useState(c.ecc);
  const box = useRef(null), qr = useRef(null);
  const [info, setInfo] = useState(null);
  useEffect(() => { setText(c.text); setEcc(c.ecc); }, [id]);
  useEffect(() => { qr.current = K().qrCode.mount(box.current, { text: c.text, ecc: c.ecc, caption: c.caption, label: c.title }); setInfo(qr.current.qr); return () => qr.current.destroy(); }, [id]);
  useEffect(() => { if (qr.current) setInfo(qr.current.update({ text, ecc, caption: text === c.text ? c.caption : undefined }).qr); }, [text, ecc]);
  return html`<div class="pv-stack">
    <${Cases} d=${d} value=${id} set=${setId}/>
    <${Sim}>${c.context} Made in the page: nothing is sent anywhere.<//>
    <div class="pv-two">
      <section><div ref=${box}></div></section>
      <section class="pv-stack">
        <label class="pv-field"><span>Text in the code: edit it and the code follows</span>
          <textarea style="width:100%;min-height:70px;font:13px/1.45 var(--f-mono);color:var(--ink);background:var(--panel);border:1px solid var(--rule);border-radius:8px;padding:8px 10px" value=${text} onInput=${e => setText(e.target.value)}></textarea></label>
        <div class="pv-row" role="group" aria-label="Error correction"><span class="pv-label">Error correction</span>${['L', 'M', 'Q', 'H'].map(x => html`<button type="button" key=${x} class=${'pv-btn' + (ecc === x ? ' pri' : '')} aria-pressed=${ecc === x} onClick=${() => setEcc(x)}>${x}</button>`)}</div>
        <p style=${LOG}>${info ? 'Version ' + info.version + ' (' + info.size + '×' + info.size + ' modules), mask ' + info.mask + ', ' + info.bytes + ' bytes. Higher error correction makes a denser code that survives more damage.' : 'Too long for a QR code at this level.'}</p>
        <div class="pv-row"><button type="button" class="pv-btn pri" onClick=${() => K().qrCode.open({ text, ecc, title: c.title, hint: c.hint, caption: text === c.text ? c.caption : undefined })}>Show it large</button></div>
      </section>
    </div></div>`;
};
})();
/* /part:page.script.preview.kit.qr-code */

/* part:page.style.kit.qr-code */
/* Kit css: QR code    kit version 0.1.0    pairs with kit/qr-code.js
   .kit-qr > figure.kit-qr-fig (div.kit-qr-code > svg, figcaption.kit-qr-cap) + div.kit-qr-acts; the sheet: .kit-qr-back > .kit-qr-sheet
   The code itself is always black on white with its quiet zone, in both themes: scanners need the contrast. Only the frame follows the theme.
   Reads --panel --ink --ink-2 --rule --accent --f-ui --f-mono, each with a plain fallback (the sheet sits on <body>); optional --radius --on-accent --shadow */
.kit-qr { display: grid; gap: 10px; justify-items: start; min-width: 0; font: 14px/1.45 var(--f-ui, system-ui, sans-serif); color: var(--ink, #16181d); }
.kit-qr-fig { margin: 0; display: grid; gap: 8px; justify-items: center; max-width: 100%; }
.kit-qr-code { width: var(--kit-qr-size, 12rem); max-width: 100%; aspect-ratio: 1; background: #fff; border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius, 6px); overflow: hidden; }
.kit-qr-code svg { display: block; width: 100%; height: 100%; }
.kit-qr-cap { max-width: var(--kit-qr-size, 12rem); font: 12.5px/1.4 var(--f-mono, ui-monospace, monospace); color: var(--ink-2, #555b66); text-align: center; overflow-wrap: anywhere; }
.kit-qr-acts { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.kit-qr-end { justify-content: flex-end; width: 100%; }
.kit-qr-btn { font: 500 13px/1.2 var(--f-ui, system-ui, sans-serif); color: var(--ink, #16181d); background: var(--panel, #fff); border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius, 6px); padding: 6px 12px; cursor: pointer; }
.kit-qr-btn:hover { filter: brightness(.97); }
.kit-qr-pri { color: var(--on-accent, #fff); background: var(--accent, #2f3b9c); border-color: var(--accent, #2f3b9c); }
.kit-qr-btn:focus-visible { outline: 3px solid var(--accent, #2f3b9c); outline-offset: 2px; }
.kit-qr-said { font-size: 12.5px; color: var(--ink-2, #555b66); }
.kit-qr-err { margin: 0; padding: 8px 10px; border: 1px solid var(--rule, #c9ced6); border-left: 3px solid var(--danger, var(--ink)); border-radius: var(--radius, 6px); color: var(--ink, #16181d); }
.kit-qr-back { position: fixed; inset: 0; z-index: 1000; display: flex; align-items: center; justify-content: center; padding: 16px; background: rgba(10, 10, 12, .72); }
.kit-qr-sheet { display: grid; gap: 12px; justify-items: center; max-width: min(36rem, 100%); max-height: calc(100vh - 32px); overflow: auto; padding: 18px; background: var(--panel, #fff); color: var(--ink, #16181d); border: 1px solid var(--rule, #c9ced6); border-radius: var(--radius-lg, 10px); box-shadow: var(--shadow, none); font-family: var(--f-ui, system-ui, sans-serif); }
.kit-qr-sheet .kit-qr { justify-items: center; }
.kit-qr-title { margin: 0; font-size: 1.15em; text-align: center; }
.kit-qr-hint { margin: 0; color: var(--ink-2, #555b66); text-align: center; max-width: 30rem; }
/* /part:page.style.kit.qr-code */

/* part:page.script.kit.qr-code */
/**
 * QR code
 * Kit.qrCode.mount(box, {text}) draws a QR code for a link or any text, as crisp SVG, with the text under it, a Copy button and a PNG download. Kit.qrCode.open({text}) shows it large on a sheet, for holding a screen up to a phone. Kit.qrCode.encode(text) is the encoder alone: it returns the module grid, so a page can draw it any way it likes. Everything runs in the page: no server, no network, no library.
 *
 * What it is: the hand-off from a screen to a phone. A signer link, a Wi-Fi guest network, a table's menu, an event check-in, a contact card. The encoder is the ISO/IEC 18004 one in byte mode (UTF-8): versions 1 to 40, error correction L, M, Q or H, the eight masks scored by the four penalty rules. It is checked module for module against a reference encoder at every version and level.
 * The code is always dark on light whatever the theme: scanners need that contrast, so the colours are options, not tokens.
 * API (small and stable):
 *   Kit.qrCode.encode(text, {ecc, minVersion, mask}) -> {version, size, ecc, mask, bytes, modules}
 *     ecc         "L" | "M" (default) | "Q" | "H": how much of the code may be damaged and still read (7, 15, 25, 30 %)
 *     minVersion  smallest version to use (default 1); mask 0..7 forces a mask (default: the lowest penalty)
 *     modules     size x size array of rows of booleans, true = dark; throws RangeError when the text does not fit version 40
 *   Kit.qrCode.svg(textOrQr, {quiet, dark, light, title}) -> SVG markup string; quiet is the margin in modules (default 4, the standard)
 *   Kit.qrCode.png(textOrQr, {scale, quiet, dark, light}) -> data URL (scale = pixels per module, default 8)
 *   Kit.qrCode.mount(box, {text, ecc, label, caption, size, quiet, copy, download, filename, onCopy}) -> {qr, update(opts), destroy()}
 *     caption     the line under the code (default: the text itself; false hides it); copy/download false hide the buttons
 *     size        CSS size of the code (default "12rem"); label: its accessible name (default "QR code")
 *   Kit.qrCode.open({text, title, hint, ecc, caption, from}) -> Promise (resolves when the sheet closes); Escape or Close closes it
 *     the sheet takes the theme tokens of from (default: the element that had focus), since it sits on <body>
 *
 * @id        kit.qr-code
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-21
 * @summary   A QR code made in the page for a link or any text: crisp SVG with the text, Copy and a PNG download, a large sheet to scan from, and the encoder alone.
 * @tags      qr, qr code, barcode, link, share, phone, scan, wifi, ticket, menu, contact, vcard, svg, png, encoder
 * @requires  none
 * @files     kit/qr-code.css, kit/samples/qr-code.json, kit/previews/qr-code.js
 * @provides  Kit.qrCode.encode, Kit.qrCode.svg, Kit.qrCode.png, Kit.qrCode.mount, Kit.qrCode.open
 * @config    Kit.qrCode.mount(box, opts) | text, ecc (L, M, Q, H), label, caption (string or false), size (CSS, default 12rem), quiet (modules, default 4), copy, download (false hides), filename, onCopy(text)
 * @config    Kit.qrCode.open(opts) | text, title, hint, ecc, caption, from (element whose theme the sheet wears); resolves when closed
 * @config    Kit.qrCode.encode(text, opts) | ecc, minVersion, mask; returns {version, size, ecc, mask, bytes, modules}
 * @tokens    --panel --ink --ink-2 --rule --accent --f-ui --f-mono --radius? --on-accent? --shadow?
 * @globals   none
 * @db        none
 * @source    Catalog harvest, 2026-11-21 | an agreement review board | the signer link shown as a QR code on the desk, made in the page instead of on a server
 * @preview   {"render": "kit.qr-code", "samples": ["kit/samples/qr-code.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };

// ---------------------------------------------------------------- tables (index 0 unused), per level L, M, Q, H
const LEVELS = { L: 0, M: 1, Q: 2, H: 3 };
const FORMAT_BITS = [1, 0, 3, 2];
const ECC_PER_BLOCK = [
  [-1, 7, 10, 15, 20, 26, 18, 20, 24, 30, 18, 20, 24, 26, 30, 22, 24, 28, 30, 28, 28, 28, 28, 30, 30, 26, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28],
  [-1, 13, 22, 18, 26, 18, 24, 18, 22, 20, 24, 28, 26, 24, 20, 30, 24, 28, 28, 26, 30, 28, 30, 30, 30, 30, 28, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30],
  [-1, 17, 28, 22, 16, 22, 28, 26, 26, 24, 28, 24, 28, 22, 24, 24, 30, 28, 28, 26, 28, 30, 24, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30, 30]];
const BLOCKS = [
  [-1, 1, 1, 1, 1, 1, 2, 2, 2, 2, 4, 4, 4, 4, 4, 6, 6, 6, 6, 7, 8, 8, 9, 9, 10, 12, 12, 12, 13, 14, 15, 16, 17, 18, 19, 19, 20, 21, 22, 24, 25],
  [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49],
  [-1, 1, 1, 2, 2, 4, 4, 6, 6, 8, 8, 8, 10, 12, 16, 12, 17, 16, 18, 21, 20, 23, 23, 25, 27, 29, 34, 34, 35, 38, 40, 43, 45, 48, 51, 53, 56, 59, 62, 65, 68],
  [-1, 1, 1, 2, 4, 4, 4, 5, 6, 8, 8, 11, 11, 16, 16, 18, 16, 19, 21, 25, 25, 25, 34, 30, 32, 35, 37, 40, 42, 45, 48, 51, 54, 57, 60, 63, 66, 70, 74, 77, 81]];

// modules left for data and error correction once the function patterns are drawn
function rawModules(v) {
  let n = (16 * v + 128) * v + 64;
  if (v >= 2) { const a = Math.floor(v / 7) + 2; n -= (25 * a - 10) * a - 55; if (v >= 7) n -= 36; }
  return n;
}
const dataCodewords = (v, e) => Math.floor(rawModules(v) / 8) - ECC_PER_BLOCK[e][v] * BLOCKS[e][v];
const countBits = v => v <= 9 ? 8 : 16;      // byte mode

function alignment(v) {
  if (v === 1) return [];
  const n = Math.floor(v / 7) + 2, size = v * 4 + 17;
  const step = v === 32 ? 26 : Math.ceil((v * 4 + 4) / (n * 2 - 2)) * 2;
  const out = [6];
  for (let p = size - 7; out.length < n; p -= step) out.splice(1, 0, p);
  return out;
}

// ---------------------------------------------------------------- Reed-Solomon over GF(2^8), polynomial 0x11D
function mul(x, y) { let z = 0; for (let i = 7; i >= 0; i--) { z = (z << 1) ^ ((z >>> 7) * 0x11D); z ^= ((y >>> i) & 1) * x; } return z & 0xFF; }
function divisor(d) {
  const r = new Array(d).fill(0); r[d - 1] = 1; let root = 1;
  for (let i = 0; i < d; i++) { for (let j = 0; j < d; j++) { r[j] = mul(r[j], root); if (j + 1 < d) r[j] ^= r[j + 1]; } root = mul(root, 2); }
  return r;
}
function remainder(data, div) {
  const r = new Array(div.length).fill(0);
  for (const b of data) { const f = b ^ r.shift(); r.push(0); div.forEach((c, i) => { r[i] ^= mul(c, f); }); }
  return r;
}

const utf8 = s => Array.from(new TextEncoder().encode(String(s)));

// ---------------------------------------------------------------- encode
function encode(text, opts = {}) {
  const ecc = String(opts.ecc || 'M').toUpperCase(), e = LEVELS[ecc];
  if (e === undefined) throw new RangeError('ecc must be L, M, Q or H');
  const bytes = utf8(text), minV = Math.max(1, Math.min(40, opts.minVersion | 0 || 1));
  let v = minV;
  for (; v <= 40; v++) if (4 + countBits(v) + 8 * bytes.length <= dataCodewords(v, e) * 8) break;
  if (v > 40) throw new RangeError('Too long for a QR code: ' + bytes.length + ' bytes; the most at level ' + ecc + ' is ' + (dataCodewords(40, e) - 3) + '.');

  // the bit stream: mode 0100, count, bytes, terminator, padding
  const bits = [];
  const put = (val, n) => { for (let i = n - 1; i >= 0; i--) bits.push((val >>> i) & 1); };
  put(4, 4); put(bytes.length, countBits(v)); bytes.forEach(b => put(b, 8));
  const cap = dataCodewords(v, e) * 8;
  put(0, Math.min(4, cap - bits.length)); put(0, (8 - bits.length % 8) % 8);
  for (let pad = 0xEC; bits.length < cap; pad ^= 0xEC ^ 0x11) put(pad, 8);
  const data = [];
  for (let i = 0; i < bits.length; i += 8) data.push(bits.slice(i, i + 8).reduce((a, b) => (a << 1) | b, 0));

  // blocks with their error correction, interleaved
  const nb = BLOCKS[e][v], el = ECC_PER_BLOCK[e][v], raw = Math.floor(rawModules(v) / 8);
  const short = nb - raw % nb, shortLen = Math.floor(raw / nb), div = divisor(el), blocks = [];
  for (let i = 0, k = 0; i < nb; i++) {
    const dat = data.slice(k, k + shortLen - el + (i < short ? 0 : 1)); k += dat.length;
    const blk = dat.concat(remainder(dat, div)); if (i < short) blk.splice(dat.length, 0, 0); blocks.push(blk);
  }
  const words = [];
  for (let i = 0; i < blocks[0].length; i++) blocks.forEach((b, j) => { if (i !== shortLen - el || j >= short) words.push(b[i]); });

  // the grid: function patterns first, then the codewords, then the best mask
  const size = v * 4 + 17;
  const grid = Array.from({ length: size }, () => new Array(size).fill(false));
  const fn = Array.from({ length: size }, () => new Array(size).fill(false));
  const set = (x, y, dark) => { grid[y][x] = dark; fn[y][x] = true; };
  for (let i = 0; i < size; i++) { set(6, i, i % 2 === 0); set(i, 6, i % 2 === 0); }
  [[3, 3], [size - 4, 3], [3, size - 4]].forEach(([cx, cy]) => {
    for (let dy = -4; dy <= 4; dy++) for (let dx = -4; dx <= 4; dx++) {
      const d = Math.max(Math.abs(dx), Math.abs(dy)), x = cx + dx, y = cy + dy;
      if (x >= 0 && x < size && y >= 0 && y < size) set(x, y, d !== 2 && d !== 4);
    }
  });
  const al = alignment(v), last = al.length - 1;
  al.forEach((ax, i) => al.forEach((ay, j) => {
    if ((i === 0 && j === 0) || (i === 0 && j === last) || (i === last && j === 0)) return;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) set(ax + dx, ay + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
  }));
  const format = mask => {
    const d = (FORMAT_BITS[e] << 3) | mask; let r = d;
    for (let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
    const b = ((d << 10) | r) ^ 0x5412, bit = i => ((b >>> i) & 1) !== 0;
    for (let i = 0; i <= 5; i++) set(8, i, bit(i));
    set(8, 7, bit(6)); set(8, 8, bit(7)); set(7, 8, bit(8));
    for (let i = 9; i < 15; i++) set(14 - i, 8, bit(i));
    for (let i = 0; i < 8; i++) set(size - 1 - i, 8, bit(i));
    for (let i = 8; i < 15; i++) set(8, size - 15 + i, bit(i));
    set(8, size - 8, true);
  };
  format(0);
  if (v >= 7) {
    let r = v; for (let i = 0; i < 12; i++) r = (r << 1) ^ ((r >>> 11) * 0x1F25);
    const b = (v << 12) | r;
    for (let i = 0; i < 18; i++) { const dark = ((b >>> i) & 1) !== 0, a = size - 11 + i % 3, c = Math.floor(i / 3); set(a, c, dark); set(c, a, dark); }
  }
  let i = 0;
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let vert = 0; vert < size; vert++) for (let j = 0; j < 2; j++) {
      const x = right - j, y = ((right + 1) & 2) === 0 ? size - 1 - vert : vert;
      if (!fn[y][x] && i < words.length * 8) { grid[y][x] = ((words[i >>> 3] >>> (7 - (i & 7))) & 1) !== 0; i++; }
    }
  }
  const MASKS = [(x, y) => (x + y) % 2 === 0, (x, y) => y % 2 === 0, x => x % 3 === 0, (x, y) => (x + y) % 3 === 0,
    (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0, (x, y) => x * y % 2 + x * y % 3 === 0,
    (x, y) => (x * y % 2 + x * y % 3) % 2 === 0, (x, y) => ((x + y) % 2 + x * y % 3) % 2 === 0];
  const apply = m => { for (let y = 0; y < size; y++) for (let x = 0; x < size; x++) if (!fn[y][x] && MASKS[m](x, y)) grid[y][x] = !grid[y][x]; };
  let mask = Number.isInteger(opts.mask) && opts.mask >= 0 && opts.mask <= 7 ? opts.mask : -1;   // null, undefined or junk: choose
  if (mask < 0) {
    let best = Infinity;
    for (let m = 0; m < 8; m++) { apply(m); format(m); const p = penalty(grid); if (p < best) { best = p; mask = m; } apply(m); }
  }
  apply(mask); format(mask);
  return { version: v, size, ecc, mask, bytes: bytes.length, modules: grid };
}

// the four penalty rules: runs, 2x2 blocks, finder-like patterns, dark balance
function penalty(g) {
  const n = g.length; let p = 0, dark = 0;
  const line = get => {
    let run = 1;
    for (let i = 1; i <= n; i++) {
      if (i < n && get(i) === get(i - 1)) run++;
      else { if (run >= 5) p += 3 + run - 5; run = 1; }
    }
    for (let i = 0; i + 7 <= n; i++) {
      if (get(i) && !get(i + 1) && get(i + 2) && get(i + 3) && get(i + 4) && !get(i + 5) && get(i + 6)) {
        const light = (a, b) => { for (let k = a; k < b; k++) if (k >= 0 && k < n && get(k)) return false; return true; };
        if (light(i - 4, i) || light(i + 7, i + 11)) p += 40;
      }
    }
  };
  for (let y = 0; y < n; y++) line(x => g[y][x]);
  for (let x = 0; x < n; x++) line(y => g[y][x]);
  for (let y = 0; y < n - 1; y++) for (let x = 0; x < n - 1; x++) { const c = g[y][x]; if (c === g[y][x + 1] && c === g[y + 1][x] && c === g[y + 1][x + 1]) p += 3; }
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (g[y][x]) dark++;
  const total = n * n;
  return p + (Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1) * 10;
}

// ---------------------------------------------------------------- drawing
const qrOf = (t, o) => (t && t.modules ? t : encode(t, o));
const escAttr = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function svg(t, o = {}) {
  const q = qrOf(t, o), m = o.quiet == null ? 4 : o.quiet, w = q.size + 2 * m;
  let d = '';
  q.modules.forEach((row, y) => { let x = 0; while (x < q.size) { if (!row[x]) { x++; continue; } let s = x; while (x < q.size && row[x]) x++; d += 'M' + (s + m) + ' ' + (y + m) + 'h' + (x - s) + 'v1h-' + (x - s) + 'z'; } });
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + w + ' ' + w + '" shape-rendering="crispEdges" role="img"' +
    (o.title ? ' aria-label="' + escAttr(o.title) + '"' : '') + '><rect width="' + w + '" height="' + w + '" fill="' + escAttr(o.light || '#fff') + '"/><path d="' + d + '" fill="' + escAttr(o.dark || '#000') + '"/></svg>';
}
function png(t, o = {}) {
  const q = qrOf(t, o), m = o.quiet == null ? 4 : o.quiet, s = o.scale || 8, w = (q.size + 2 * m) * s;
  const c = document.createElement('canvas'); c.width = c.height = w; const x = c.getContext('2d');
  x.fillStyle = o.light || '#fff'; x.fillRect(0, 0, w, w); x.fillStyle = o.dark || '#000';
  q.modules.forEach((row, y) => row.forEach((on, i) => { if (on) x.fillRect((i + m) * s, (y + m) * s, s, s); }));
  return c.toDataURL('image/png');
}

const TOKENS = ['--panel', '--ink', '--ink-2', '--rule', '--accent', '--on-accent', '--danger', '--f-ui', '--f-mono', '--radius', '--radius-lg', '--shadow'];
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
